-- Folio / TiDB Cloud schema v1.  Review before applying; no destructive statements.
-- Target: a dedicated application database, NOT TiDB system schema.
-- UUIDs are generated by the application. Times are UTC DATETIME(3).
CREATE TABLE IF NOT EXISTS folio_clusters (
  id CHAR(36) NOT NULL,
  slug VARCHAR(64) NOT NULL,
  name VARCHAR(80) NOT NULL,
  blurb VARCHAR(500) NOT NULL DEFAULT '',
  sort_index INT NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_folio_clusters_slug (slug),
  KEY idx_folio_clusters_sort (sort_index, id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS folio_entries (
  id CHAR(36) NOT NULL,
  slug VARCHAR(64) NOT NULL,
  kind ENUM('note','work') NOT NULL,
  title VARCHAR(120) NOT NULL,
  dek VARCHAR(280) NOT NULL,
  cover VARCHAR(240) NOT NULL DEFAULT '',
  cover_alt VARCHAR(160) NOT NULL DEFAULT '',
  body_json JSON NOT NULL,
  cluster_id CHAR(36) NOT NULL,
  visibility ENUM('public','private') NOT NULL DEFAULT 'private',
  status ENUM('draft','published') NOT NULL DEFAULT 'draft',
  published_at DATETIME(3) NULL,
  reading_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 5,
  featured TINYINT(1) NOT NULL DEFAULT 0,
  tags_json JSON NOT NULL,
  year VARCHAR(8) NOT NULL DEFAULT '',
  role VARCHAR(80) NOT NULL DEFAULT '',
  outcome VARCHAR(160) NOT NULL DEFAULT '',
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY uq_folio_entries_slug (slug),
  KEY idx_folio_entries_public (visibility, status, published_at),
  KEY idx_folio_entries_cluster (cluster_id, updated_at),
  KEY idx_folio_entries_featured (featured, published_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS folio_callbacks (
  id CHAR(36) NOT NULL,
  entry_id CHAR(36) NOT NULL,
  event_type VARCHAR(100) NOT NULL,
  target_url VARCHAR(1024) NOT NULL DEFAULT '',
  status_code SMALLINT UNSIGNED NULL,
  ok TINYINT(1) NOT NULL DEFAULT 0,
  detail TEXT NOT NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY idx_folio_callbacks_created (created_at),
  KEY idx_folio_callbacks_entry (entry_id, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

CREATE TABLE IF NOT EXISTS folio_schema_migrations (
  version VARCHAR(100) NOT NULL,
  checksum CHAR(64) NOT NULL,
  applied_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
